Object.assign(window.EXAMPLES=window.EXAMPLES||{},{"ottoman":{"t":"The Ottoman Empire through time","c":"The Ottoman Empire began as a small Turkish state in Anatolia around 1299 and grew into one of history’s great powers. After Sultan Mehmed II captured Constantinople in 1453, renaming it Istanbul, the empire spread across south-eastern Europe, the Middle East and North Africa, reaching its peak under Suleiman the Magnificent. For centuries it was a centre of trade, architecture and learning, ruling many peoples and faiths. It declined from the 1700s and was dissolved after defeat in the First World War, replaced by the Republic of Turkey.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#b91c1c\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1299</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Osman I founds the dynasty</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#b91c1c\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1453</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mehmed II captures Constantinople</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#b91c1c\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1520–66</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Suleiman the Magnificent: empire at its height</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#b91c1c\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1683</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Siege of Vienna fails</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#b91c1c\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1922</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sultanate abolished; Turkish Republic follows in 1923</text></svg>","c":"Milestones of the Ottoman Empire"}]},"explor":{"t":"Voyages of the Age of Exploration","c":"From the 1400s European sailors, led by Portugal and Spain, used improved ships, compasses and maps to venture across the oceans, seeking sea routes to the spice markets of Asia. They reached Africa’s southern tip, the Americas, India and the Pacific, and completed the first circumnavigation of the globe. The voyages connected the world’s continents and led to vast trade, the exchange of crops and animals, and the spread of European colonial empires, but also to the conquest of Indigenous peoples, devastating epidemics and the Atlantic slave trade.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#0369a1\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1488</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Bartolomeu Dias rounds the Cape of Good Hope</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#0369a1\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1492</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Columbus reaches the Caribbean</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#0369a1\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1498</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Vasco da Gama reaches India by sea</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#0369a1\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1519–22</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Magellan–Elcano expedition sails around the world</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#0369a1\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1606</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Willem Janszoon’s crew lands in Australia</text></svg>","c":"Some landmark voyages"}]},"usrev":{"t":"The American Revolution","c":"Thirteen British colonies on the east coast of North America grew angry at taxes imposed by a Parliament in which they had no representatives: ‘no taxation without representation’. Protests turned into war in 1775, and in 1776 the Continental Congress adopted the Declaration of Independence, drafted largely by Thomas Jefferson. With help from France, Spain and the Netherlands, George Washington’s army forced a British surrender at Yorktown in 1781. Its ideals of liberty inspired revolutions elsewhere, though they were not then extended to enslaved people or Native Americans.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 288\" width=\"640\" height=\"288\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"272\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1765</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Stamp Act angers the colonists</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1773</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Boston Tea Party</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1775</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">War begins at Lexington and Concord</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">4 July 1776</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Declaration of Independence</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1781</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">British surrender at Yorktown</text><circle cx=\"140\" cy=\"244\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"249\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1783</text><text x=\"156\" y=\"249\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Treaty of Paris recognises US independence</text></svg>","c":"From protest to independence"}]},"uscivilwar":{"t":"The American Civil War","c":"The American Civil War, from 1861 to 1865, was fought between the United States, or the Union, and eleven Southern states that broke away to form the Confederacy, mainly to preserve slavery. It was the deadliest war in American history, with an estimated 620,000 to 750,000 soldiers killed. President Abraham Lincoln’s Emancipation Proclamation of 1863 declared enslaved people in rebel areas free, and the Union victory was followed by the 13th Amendment, which abolished slavery throughout the country. Lincoln was assassinated days after the war ended.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 204\" width=\"640\" height=\"204\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"188\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#334155\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1861</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Southern states secede; war begins at Fort Sumter</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#334155\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1863</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Emancipation Proclamation; Battle of Gettysburg</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#334155\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1865</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Confederate surrender at Appomattox; Lincoln assassinated</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#334155\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1865</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">13th Amendment abolishes slavery</text></svg>","c":"Key events of the war"}]},"russrev":{"t":"The Russian Revolution","c":"In 1917, exhausted by the First World War, food shortages and centuries of autocratic rule, Russia went through two revolutions. In February, protests in Petrograd forced Tsar Nicholas II to abdicate, ending three centuries of Romanov rule. In October, the Bolsheviks, a communist party led by Vladimir Lenin, overthrew the provisional government. A brutal civil war followed, and in 1922 the Bolsheviks founded the Union of Soviet Socialist Republics, the world’s first communist state, which lasted until 1991. Dates use the old Russian calendar.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 204\" width=\"640\" height=\"204\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"188\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1917 (Feb)</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tsar Nicholas II abdicates</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1917 (Oct)</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Bolsheviks under Lenin seize power</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1918–21</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Civil war between Reds and Whites</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1922</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Soviet Union founded</text></svg>","c":"The revolutions of 1917 and after"}]},"meiji":{"t":"Meiji Japan transforms itself","c":"After American warships forced Japan to open its ports in 1853–54, reformers overthrew the shogun and in 1868 restored power to the young Emperor Meiji. In just a few decades Japan abolished the samurai class and feudal domains, built railways, factories, schools and a modern army and navy, and adopted a constitution in 1889. By defeating China in 1895 and Russia in 1905, it became the first non-Western industrial and imperial power of the modern era. The speed of change was among the fastest any country has achieved.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#be123c\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1868</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Meiji Restoration: emperor restored to power</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#be123c\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1871</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Feudal domains abolished</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#be123c\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1872</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">First railway, Tokyo to Yokohama</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#be123c\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1889</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Meiji Constitution</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#be123c\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1905</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Japan defeats Russia</text></svg>","c":"Landmarks of the Meiji era"}]},"mughal":{"t":"The Mughal Empire","c":"The Mughal Empire was founded in 1526 by Babur, a descendant of Timur and Genghis Khan from Central Asia, and came to rule most of the Indian subcontinent. Under emperors such as Akbar, known for religious tolerance, it was among the richest and most populous states in the world, famous for art, architecture and miniature painting; Shah Jahan built the Taj Mahal as a tomb for his wife. After Aurangzeb’s death in 1707 it weakened, and the British exiled the last emperor after the rebellion of 1857.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#15803d\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1526</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Babur wins the Battle of Panipat</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#15803d\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1556–1605</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Akbar expands and unites the empire</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#15803d\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1632–53</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Shah Jahan builds the Taj Mahal</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#15803d\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1658–1707</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Aurangzeb: greatest extent</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#15803d\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1857</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Last emperor exiled by the British</text></svg>","c":"Milestones of the Mughal Empire"}]},"khmer":{"t":"The Khmer Empire","c":"From the 9th to the 15th centuries the Khmer Empire dominated much of mainland Southeast Asia from its capital at Angkor in present-day Cambodia. Its kings built hundreds of temples, including Angkor Wat, the largest religious monument in the world, and a vast network of reservoirs and canals that supported a city of perhaps a million people. The empire shifted from Hinduism to Buddhism. It declined after the 13th century, possibly because of wars, droughts, floods and changing trade, and the capital moved south after 1431.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 204\" width=\"640\" height=\"204\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"188\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#78716c\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">9th c.</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Khmer kingdom founded</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#78716c\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">c. 1113–1150</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Angkor Wat built under Suryavarman II</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#78716c\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">c. 1200</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Jayavarman VII builds Angkor Thom and the Bayon</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#78716c\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1431</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Angkor sacked; capital moves south</text></svg>","c":"Milestones of the Khmer Empire"}]},"enlightenment":{"t":"Ideas of the Enlightenment","c":"The Enlightenment was an intellectual movement in 17th- and 18th-century Europe that championed reason, science and individual rights over tradition and absolute authority. Thinkers such as John Locke argued for natural rights to life, liberty and property; Montesquieu proposed separating government powers; Voltaire defended free speech and religious tolerance; and Jean-Jacques Rousseau wrote of the social contract. Their ideas inspired the American and French revolutions and shaped modern democracy, though many thinkers of the time did not extend these rights to all people.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 170\" width=\"610\" height=\"170\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"40\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">John Locke</text><text x=\"24\" y=\"60\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Natural rights: life, liberty, property</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"40\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Montesquieu</text><text x=\"324\" y=\"60\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Separate the powers of government</text><rect x=\"10\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"120\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Voltaire</text><text x=\"24\" y=\"140\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Free speech and religious tolerance</text><rect x=\"310\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"120\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Rousseau</text><text x=\"324\" y=\"140\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The social contract</text></svg>","c":"Four Enlightenment thinkers and their key ideas"}]},"constitution":{"t":"The separation of powers","c":"A constitution is a country’s highest law, setting out how it is governed and what rights citizens have. Many constitutions divide power among three branches so no single person or group has too much: a legislature makes laws, an executive carries them out, and an independent judiciary interprets them and can strike down actions that break the constitution. This idea, championed by Montesquieu, shaped the US Constitution of 1787, the oldest written national constitution still in use, and many since. Countries arrange the branches in different ways.","items":[{"w":1,"s":"<svg viewBox=\"0 0 600 250\" width=\"600\" height=\"250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"580\" height=\"70\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"40\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Lawmaking</text><text x=\"24\" y=\"60\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Parliament or congress debates and passes laws</text><rect x=\"10\" y=\"90\" width=\"580\" height=\"70\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"120\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Executive</text><text x=\"24\" y=\"140\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The president or government carries them out</text><rect x=\"10\" y=\"170\" width=\"580\" height=\"70\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"24\" y=\"200\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Judiciary</text><text x=\"24\" y=\"220\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Courts interpret laws and settle disputes</text></svg>","c":"Three branches of government"}]},"elections":{"t":"How an election works","c":"In democracies, citizens choose their leaders and representatives in regular, free elections. The basic steps are similar everywhere: eligible people register to vote, candidates and parties campaign, voters cast secret ballots, and officials count the votes under the watch of observers before announcing results. Countries use different voting systems: in first-past-the-post, the candidate with the most votes in each area wins, while proportional systems give parties seats roughly matching their share of votes. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 110\" width=\"640\" height=\"110\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:640px;max-width:100%;height:auto\"><rect x=\"10\" y=\"20\" width=\"100\" height=\"70\" rx=\"10\" fill=\"#bfdbfe\"/><text x=\"60\" y=\"52\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Register</text><text x=\"60\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">sign up</text><path d=\"M110,55H132\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M140,55l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"140\" y=\"20\" width=\"100\" height=\"70\" rx=\"10\" fill=\"#fde68a\"/><text x=\"190\" y=\"52\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Campaign</text><text x=\"190\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">share ideas</text><path d=\"M240,55H262\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M270,55l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"270\" y=\"20\" width=\"100\" height=\"70\" rx=\"10\" fill=\"#bbf7d0\"/><text x=\"320\" y=\"52\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Vote</text><text x=\"320\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">secret ballot</text><path d=\"M370,55H392\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M400,55l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"400\" y=\"20\" width=\"100\" height=\"70\" rx=\"10\" fill=\"#e9d5ff\"/><text x=\"450\" y=\"52\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Count</text><text x=\"450\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">tally, check</text><path d=\"M500,55H522\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M530,55l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"530\" y=\"20\" width=\"100\" height=\"70\" rx=\"10\" fill=\"#fecaca\"/><text x=\"580\" y=\"52\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Result</text><text x=\"580\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">take office</text></svg>","c":"The main stages of an election"}]},"gunpowder":{"t":"Gunpowder spreads from China","c":"Gunpowder, a mixture of saltpetre, charcoal and sulphur, was discovered by Chinese alchemists around the 9th century, reportedly while searching for an elixir of life. The Chinese first used it for fireworks and then for fire arrows, rockets, bombs and early guns. The knowledge spread along trade routes and through the Mongol conquests to the Islamic world and Europe by the 1200s and 1300s, where cannons and handguns transformed warfare, ending the age of castles and armoured knights. It remains in fireworks, blasting and mining today.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">9th c.</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Discovered by Chinese alchemists</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">10th c.</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Fire arrows and fire lances in China</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1200s</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Spreads via the Mongols and trade</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1300s</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cannons appear in Europe and the Middle East</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1500s</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Muskets reshape warfare worldwide</text></svg>","c":"The spread of gunpowder"}]},"homer":{"t":"Features of an epic poem","c":"The Iliad and the Odyssey, traditionally credited to the Greek poet Homer and probably composed in the 8th or 7th century BC, are among the oldest works of Western literature. The Iliad tells of the Trojan War and the rage of Achilles; the Odyssey follows Odysseus on his ten-year journey home. They were sung aloud before being written down, using repeated phrases such as ‘rosy-fingered dawn’ to help performers remember. Epics share common features found also in Gilgamesh, the Mahabharata, the Ramayana and the Sundiata.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 170\" width=\"610\" height=\"170\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"24\" y=\"40\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Invocation</text><text x=\"24\" y=\"60\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The poet asks the Muse for help</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"324\" y=\"40\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">In medias res</text><text x=\"324\" y=\"60\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The story starts in the middle</text><rect x=\"10\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"120\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Epic hero</text><text x=\"24\" y=\"140\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">A great warrior or traveller</text><rect x=\"310\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"120\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Long journey or war</text><text x=\"324\" y=\"140\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Gods take sides</text></svg>","c":"Common features of epic poems"}]},"austen":{"t":"Jane Austen’s novels","c":"Jane Austen, an English novelist who lived from 1775 to 1817, wrote six major novels about the lives, loves and marriages of the English gentry. Her sharp wit, irony and close observation of character made her one of the most widely read writers in the English language, and her books are endlessly adapted for film and television. They were published anonymously, credited only to ‘a Lady’. Pride and Prejudice, with its famous opening line about a single man in possession of a good fortune, has sold over 20 million copies.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#be185d\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1811</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sense and Sensibility</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#be185d\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1813</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Pride and Prejudice</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#be185d\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1814</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mansfield Park</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#be185d\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1815</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Emma</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#be185d\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1817–18</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Northanger Abbey and Persuasion (after her death)</text></svg>","c":"Publication dates of her six major novels"}]},"reform":{"t":"The Reformation","c":"In 1517 Martin Luther, a German monk, published criticisms of the Catholic Church, especially the sale of indulgences, which promised reduced punishment for sins. Spread rapidly by the new printing press, his ideas split Western Christianity. Protestant churches, including Lutheran, Calvinist and Anglican ones, rejected the authority of the pope and emphasised faith and the Bible in local languages. The Catholic Church responded with its own reforms. The divisions led to wars across Europe for over a century, until the Peace of Westphalia in 1648.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1517</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Martin Luther’s Ninety-five Theses</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1521</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Luther excommunicated</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1534</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Henry VIII founds the Church of England</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1536</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">John Calvin publishes his Institutes</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1545–63</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Council of Trent: the Catholic Reformation</text></svg>","c":"Milestones of the Reformation"}]},"gmyth":{"t":"Some Olympian gods","c":"The ancient Greeks believed in a family of gods who lived on Mount Olympus, behaving much like humans, with loves, rivalries and jealousies. Zeus ruled the sky, his brother Poseidon the sea and Hades the underworld. Myths about them, and about heroes such as Heracles, Perseus and Odysseus, explained the natural world and taught lessons about pride and fate. The Romans adopted many of these gods under Latin names, such as Jupiter for Zeus, and the planets still bear those Roman names.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 250\" width=\"610\" height=\"250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#facc15\" fill-opacity=\".2\" stroke=\"#facc15\"/><text x=\"24\" y=\"40\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Zeus</text><text x=\"24\" y=\"60\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">King of the gods, sky and thunder</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#a855f7\" fill-opacity=\".2\" stroke=\"#a855f7\"/><text x=\"324\" y=\"40\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Hera</text><text x=\"324\" y=\"60\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Queen of the gods, marriage</text><rect x=\"10\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"120\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Poseidon</text><text x=\"24\" y=\"140\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sea and earthquakes</text><rect x=\"310\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#64748b\" fill-opacity=\".2\" stroke=\"#64748b\"/><text x=\"324\" y=\"120\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Athena</text><text x=\"324\" y=\"140\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wisdom and war strategy</text><rect x=\"10\" y=\"170\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"24\" y=\"200\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Apollo</text><text x=\"24\" y=\"220\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sun, music and prophecy</text><rect x=\"310\" y=\"170\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"200\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Artemis</text><text x=\"324\" y=\"220\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The hunt and the moon</text></svg>","c":"Six of the twelve Olympians"}]},"norsemyth":{"t":"Gods of Norse mythology","c":"Norse mythology, told by the Vikings and other Scandinavian peoples and preserved in Icelandic texts such as the Eddas, describes nine worlds held in the branches and roots of a giant ash tree, Yggdrasil. The gods lived in Asgard, humans in Midgard, and frost giants in Jotunheim. The myths foretell Ragnarök, a final battle in which many gods die and the world is reborn. Several English weekdays are named after Norse gods: Wednesday after Odin, also called Woden, Thursday after Thor and Friday after Frigg.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 170\" width=\"610\" height=\"170\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#475569\" fill-opacity=\".2\" stroke=\"#475569\"/><text x=\"24\" y=\"40\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Odin</text><text x=\"24\" y=\"60\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Chief god; wisdom and war</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"324\" y=\"40\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Thor</text><text x=\"324\" y=\"60\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Thunder; wields the hammer Mjölnir</text><rect x=\"10\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#ec4899\" fill-opacity=\".2\" stroke=\"#ec4899\"/><text x=\"24\" y=\"120\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Freyja</text><text x=\"24\" y=\"140\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Love, beauty and war</text><rect x=\"310\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"120\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Loki</text><text x=\"324\" y=\"140\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Trickster and shapeshifter</text></svg>","c":"Four of the main Norse gods"}]},"fairy":{"t":"Common features of fairy tales","c":"Fairy tales are short traditional stories, usually involving magic, that were passed on by word of mouth for centuries before collectors wrote them down: Charles Perrault in France in 1697, the Brothers Grimm in Germany from 1812, and Hans Christian Andersen in Denmark, who also wrote his own. Similar stories appear in many cultures; Cinderella has versions from ancient Egypt and 9th-century China. Folklorists have catalogued thousands of tale types and their recurring features.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 170\" width=\"610\" height=\"170\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"24\" y=\"40\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Once upon a time</text><text x=\"24\" y=\"60\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">A timeless setting</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"324\" y=\"40\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Rule of three</text><text x=\"324\" y=\"60\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Three wishes, sisters or tasks</text><rect x=\"10\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"120\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Magic helper</text><text x=\"24\" y=\"140\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">A fairy godmother, talking animal</text><rect x=\"310\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"324\" y=\"120\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Happily ever after</text><text x=\"324\" y=\"140\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Good is rewarded</text></svg>","c":"Patterns found in many fairy tales"}]},"mozart":{"t":"Sonata form","c":"Wolfgang Amadeus Mozart, who lived from 1756 to 1791, composed over 600 works, including symphonies, operas, concertos and chamber music, in a life of only 35 years. Like other composers of the Classical period, such as Haydn and the young Beethoven, he often built movements in sonata form: an exposition presents two contrasting musical themes, a development section explores and transforms them, and a recapitulation brings them back in the home key. A child prodigy, he performed for European royalty from the age of six.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 110\" width=\"620\" height=\"110\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><rect x=\"10\" y=\"20\" width=\"180\" height=\"70\" rx=\"10\" fill=\"#bfdbfe\"/><text x=\"100\" y=\"52\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Exposition</text><text x=\"100\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">Two themes introduced</text><path d=\"M190,55H212\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M220,55l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"220\" y=\"20\" width=\"180\" height=\"70\" rx=\"10\" fill=\"#fde68a\"/><text x=\"310\" y=\"52\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Development</text><text x=\"310\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">Themes explored</text><path d=\"M400,55H422\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M430,55l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"430\" y=\"20\" width=\"180\" height=\"70\" rx=\"10\" fill=\"#bbf7d0\"/><text x=\"520\" y=\"52\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Recapitulation</text><text x=\"520\" y=\"70\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">Themes return</text></svg>","c":"The three main sections of sonata form"}]},"reggae":{"t":"The reggae skank","c":"Reggae developed in Jamaica in the late 1960s from earlier styles called ska and rocksteady. Its signature is the ‘skank’, short guitar or keyboard chords played on the off-beats, beats two and four, over a deep, prominent bassline and a laid-back drum pattern. Bob Marley and the Wailers made reggae famous worldwide in the 1970s with songs about love, faith, social justice and Rastafari. In 2018 UNESCO added reggae music of Jamaica to its list of intangible cultural heritage.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 180\" width=\"620\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"180\" rx=\"10\" fill=\"#f8fafc\"/><line x1=\"60\" y1=\"40\" x2=\"60\" y2=\"140\" stroke=\"currentColor\" stroke-opacity=\".2\"/><text x=\"60\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1</text><line x1=\"128\" y1=\"40\" x2=\"128\" y2=\"140\" stroke=\"currentColor\" stroke-opacity=\".2\"/><text x=\"128\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2</text><line x1=\"196\" y1=\"40\" x2=\"196\" y2=\"140\" stroke=\"currentColor\" stroke-opacity=\".2\"/><text x=\"196\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">3</text><line x1=\"264\" y1=\"40\" x2=\"264\" y2=\"140\" stroke=\"currentColor\" stroke-opacity=\".2\"/><text x=\"264\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">4</text><line x1=\"332\" y1=\"40\" x2=\"332\" y2=\"140\" stroke=\"currentColor\" stroke-opacity=\".2\"/><text x=\"332\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1</text><line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"140\" stroke=\"currentColor\" stroke-opacity=\".2\"/><text x=\"400\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2</text><line x1=\"468\" y1=\"40\" x2=\"468\" y2=\"140\" stroke=\"currentColor\" stroke-opacity=\".2\"/><text x=\"468\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">3</text><line x1=\"536\" y1=\"40\" x2=\"536\" y2=\"140\" stroke=\"currentColor\" stroke-opacity=\".2\"/><text x=\"536\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">4</text><rect x=\"42\" y=\"110\" width=\"36\" height=\"22\" rx=\"5\" fill=\"#94a3b8\"/><rect x=\"178\" y=\"110\" width=\"36\" height=\"22\" rx=\"5\" fill=\"#94a3b8\"/><rect x=\"314\" y=\"110\" width=\"36\" height=\"22\" rx=\"5\" fill=\"#94a3b8\"/><rect x=\"450\" y=\"110\" width=\"36\" height=\"22\" rx=\"5\" fill=\"#94a3b8\"/><rect x=\"110\" y=\"60\" width=\"36\" height=\"22\" rx=\"5\" fill=\"#16a34a\"/><rect x=\"246\" y=\"60\" width=\"36\" height=\"22\" rx=\"5\" fill=\"#16a34a\"/><rect x=\"382\" y=\"60\" width=\"36\" height=\"22\" rx=\"5\" fill=\"#16a34a\"/><rect x=\"518\" y=\"60\" width=\"36\" height=\"22\" rx=\"5\" fill=\"#16a34a\"/><text x=\"310\" y=\"166\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Guitar chops land on the off-beats (green)</text></svg>","c":"Off-beat chords over a steady beat (simplified)"}]},"swimming":{"t":"The four competitive strokes","c":"Competitive swimming uses four strokes. Freestyle, almost always front crawl, is the fastest. Backstroke is swum on the back. Breaststroke is the slowest, with a frog-like kick. Butterfly, the most tiring, moves both arms over the water together with an undulating dolphin kick. Individual medley races combine all four. Swimming has been in every modern Olympic Games since 1896. Michael Phelps of the United States won a record 23 Olympic gold medals, most of them in the pool’s individual and relay events.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 170\" width=\"610\" height=\"170\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"40\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Freestyle (front crawl)</text><text x=\"24\" y=\"60\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Fastest; arms alternate</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"40\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Backstroke</text><text x=\"324\" y=\"60\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">On the back</text><rect x=\"10\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"24\" y=\"120\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Breaststroke</text><text x=\"24\" y=\"140\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Arms and legs move together</text><rect x=\"310\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"324\" y=\"120\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Butterfly</text><text x=\"324\" y=\"140\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Both arms together; dolphin kick</text></svg>","c":"The four strokes used in races"}]},"martial":{"t":"Martial arts around the world","c":"Martial arts are systems of combat and self-defence developed in many cultures, often also practised for fitness, discipline and sport. Karate, judo and taekwondo are Olympic sports; boxing, with roots in ancient Greece and England, has been in the Olympics since 1904. Martial arts often use colored belts to mark progress, a system introduced for judo in Japan in the late 1800s. Others include Brazilian capoeira, Israeli krav maga and Filipino arnis, also called eskrima or kali.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 250\" width=\"610\" height=\"250\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"40\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Karate</text><text x=\"24\" y=\"60\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Japan (Okinawa): Strikes and kicks</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"324\" y=\"40\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Taekwondo</text><text x=\"324\" y=\"60\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Korea: High, fast kicks</text><rect x=\"10\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#64748b\" fill-opacity=\".2\" stroke=\"#64748b\"/><text x=\"24\" y=\"120\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Judo</text><text x=\"24\" y=\"140\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Japan: Throws and holds</text><rect x=\"310\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"324\" y=\"120\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Kung fu</text><text x=\"324\" y=\"140\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">China: Many styles</text><rect x=\"10\" y=\"170\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"200\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Muay Thai</text><text x=\"24\" y=\"220\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Thailand: Elbows, knees, shins</text><rect x=\"310\" y=\"170\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"200\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Arnis</text><text x=\"324\" y=\"220\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Philippines: Sticks and blades</text></svg>","c":"Six martial arts and where they come from"}]},"malaria":{"t":"The malaria cycle","c":"Malaria is caused by Plasmodium parasites spread by the bites of infected female Anopheles mosquitoes. The parasites travel to the liver, multiply, then invade red blood cells, causing fever, chills and, without treatment, sometimes death. When another mosquito bites the infected person, it picks up parasites and passes them on. Malaria still kills over 600,000 people a year, mostly young children in Africa. Insecticide-treated bed nets, medicines and, since 2021, the first malaria vaccines are cutting cases. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#f8fafc\"/><rect x=\"20\" y=\"60\" width=\"130\" height=\"70\" rx=\"10\" fill=\"#fde68a\"/><text x=\"85\" y=\"92\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Infected mosquito</text><text x=\"85\" y=\"110\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">bites a person</text><path d=\"M150,95H182\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M190,95l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"190\" y=\"60\" width=\"120\" height=\"70\" rx=\"10\" fill=\"#fecaca\"/><text x=\"250\" y=\"92\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Liver</text><text x=\"250\" y=\"110\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">parasites multiply</text><path d=\"M310,95H342\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M350,95l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"350\" y=\"60\" width=\"120\" height=\"70\" rx=\"10\" fill=\"#fca5a5\"/><text x=\"410\" y=\"92\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Red blood cells</text><text x=\"410\" y=\"110\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">fever and chills</text><path d=\"M470,95H492\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M500,95l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"500\" y=\"60\" width=\"110\" height=\"70\" rx=\"10\" fill=\"#e9d5ff\"/><text x=\"555\" y=\"92\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">New mosquito</text><text x=\"555\" y=\"110\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">bites and carries it on</text><text x=\"310\" y=\"170\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Prevention: bed nets, repellents, vaccines and treatment</text></svg>","c":"How malaria passes between mosquitoes and people"}]},"leptospirosis":{"t":"How leptospirosis spreads","c":"Leptospirosis is a bacterial disease spread mainly through water or soil contaminated by the urine of infected animals, especially rats. It is common in tropical countries after floods and heavy rain, when people wade through flood water. The bacteria enter through cuts, scratches, or the eyes, nose and mouth. Symptoms such as fever, headache and muscle pain can be mild, but severe cases can damage the kidneys and liver. Wearing boots, covering wounds and seeing a doctor quickly after exposure all help. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 160\" width=\"620\" height=\"160\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#f8fafc\"/><rect x=\"20\" y=\"60\" width=\"150\" height=\"70\" rx=\"10\" fill=\"#fde68a\"/><text x=\"95\" y=\"92\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Flood water</text><text x=\"95\" y=\"110\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">with animal urine</text><path d=\"M170,95H202\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M210,95l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"210\" y=\"60\" width=\"180\" height=\"70\" rx=\"10\" fill=\"#fecaca\"/><text x=\"300\" y=\"92\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Enters through</text><text x=\"300\" y=\"110\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">cuts or eyes and mouth</text><path d=\"M390,95H422\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M430,95l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"430\" y=\"60\" width=\"170\" height=\"70\" rx=\"10\" fill=\"#bbf7d0\"/><text x=\"515\" y=\"92\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">See a doctor early</text><text x=\"515\" y=\"110\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">antibiotics work</text></svg>","c":"Leptospirosis: from flood water to illness"}]},"tokyo":{"t":"The world’s biggest cities","c":"Tokyo, the capital of Japan, has for decades been the largest urban area in the world, home to about 37 million people in its wider metropolitan region. It is famous for its efficiency: its trains carry millions of passengers daily and are known for punctuality. Recent UN estimates using new methods suggest some rapidly growing cities, such as Jakarta and Dhaka, may now be even larger. City populations depend on where the boundaries are drawn, so rankings differ between sources. Figures are approximate metropolitan populations.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 264\" width=\"620\" height=\"264\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"140\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tokyo</text><rect x=\"150\" y=\"12\" width=\"330.0\" height=\"28\" rx=\"5\" fill=\"#dc2626\"/><text x=\"488\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">37 million</text><text x=\"140\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Delhi</text><rect x=\"150\" y=\"52\" width=\"303.2\" height=\"28\" rx=\"5\" fill=\"#f59e0b\"/><text x=\"461.2432432432432\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">34 million</text><text x=\"140\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Shanghai</text><rect x=\"150\" y=\"92\" width=\"267.6\" height=\"28\" rx=\"5\" fill=\"#2563eb\"/><text x=\"425.56756756756755\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">30 million</text><text x=\"140\" y=\"151\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dhaka</text><rect x=\"150\" y=\"132\" width=\"214.1\" height=\"28\" rx=\"5\" fill=\"#16a34a\"/><text x=\"372.05405405405406\" y=\"151\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">24 million</text><text x=\"140\" y=\"191\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">São Paulo</text><rect x=\"150\" y=\"172\" width=\"205.1\" height=\"28\" rx=\"5\" fill=\"#7c3aed\"/><text x=\"363.1351351351351\" y=\"191\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">23 million</text><text x=\"140\" y=\"231\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cairo</text><rect x=\"150\" y=\"212\" width=\"196.2\" height=\"28\" rx=\"5\" fill=\"#a16207\"/><text x=\"354.21621621621625\" y=\"231\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">22 million</text></svg>","c":"Approximate metropolitan populations (UN estimates, early 2020s)"}]},"cairo":{"t":"Cairo on the Nile","c":"Cairo, the capital of Egypt, is the largest city in Africa and the Arab world, with over 20 million people in its metropolitan area. It grew on the banks of the Nile, just south of where the river fans out into its delta, and the Pyramids of Giza stand on the desert plateau at its western edge. Its historic centre is famous for hundreds of medieval mosques, and Al-Azhar, founded in 970, is one of the oldest universities in the world. Schematic, not to scale.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#fef3c7\"/><path d=\"M20,120Q160,110 300,130T600,120V200H20Z\" fill=\"#d6c7a1\"/><path d=\"M300,20Q290,90 310,120Q330,160 300,200\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"14\"/><rect x=\"320\" y=\"90\" width=\"30\" height=\"20\" fill=\"#78716c\"/><rect x=\"360\" y=\"80\" width=\"40\" height=\"30\" fill=\"#a8a29e\"/><text x=\"360\" y=\"70\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cairo</text><path d=\"M180,120L210,80L240,120Z\" fill=\"#d6b779\"/><path d=\"M220,120L240,92L260,120Z\" fill=\"#d6b779\"/><text x=\"220\" y=\"140\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Pyramids of Giza</text><text x=\"300\" y=\"190\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">The Nile</text></svg>","c":"Cairo, the Nile and the pyramids (schematic)"}]},"istanbul":{"t":"A city on two continents","c":"Istanbul, Turkey’s largest city, straddles the Bosphorus, the narrow strait linking the Black Sea and the Sea of Marmara, so it lies partly in Europe and partly in Asia. Founded as Byzantium, it became Constantinople, capital of the Roman and then Byzantine Empire, and later the capital of the Ottoman Empire after 1453. Landmarks such as the Hagia Sophia, built as a church in 537, reflect its layered history. Bridges and a rail tunnel under the strait connect the two sides. Schematic.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#e0f2fe\"/><path d=\"M0,70H620V200H0Z\" fill=\"#86efac\"/><path d=\"M290,0L310,0L320,200L300,200Z\" fill=\"#38bdf8\"/><text x=\"160\" y=\"120\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"900\" fill=\"#14532d\" font-family=\"system-ui,sans-serif\">EUROPE</text><text x=\"470\" y=\"120\" text-anchor=\"middle\" font-size=\"18\" font-weight=\"900\" fill=\"#14532d\" font-family=\"system-ui,sans-serif\">ASIA</text><text x=\"310\" y=\"180\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Bosphorus Strait</text><text x=\"310\" y=\"40\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Istanbul spans both continents</text></svg>","c":"Istanbul spread across the Bosphorus (schematic)"}]},"rio":{"t":"Rio de Janeiro’s landscape","c":"Rio de Janeiro, Brazil’s second-largest city and its capital until 1960, is famous for one of the world’s most dramatic urban settings, squeezed between granite mountains, forest and the Atlantic. The statue of Christ the Redeemer, 30 metres tall and completed in 1931, overlooks the city from Corcovado mountain, and cable cars climb Sugarloaf Mountain at the mouth of Guanabara Bay. Its Carnival, beaches such as Copacabana and Ipanema, and samba music draw visitors from around the world. Schematic.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 220\" width=\"620\" height=\"220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"220\" rx=\"10\" fill=\"#e0f2fe\"/><path d=\"M0,220V160Q100,150 200,170T420,160T620,170V220Z\" fill=\"#0284c7\"/><path d=\"M250,160L300,40L340,160Z\" fill=\"#65a30d\"/><path d=\"M298,40v-30M286,26h24\" stroke=\"#78716c\" stroke-width=\"5\"/><path d=\"M420,160Q450,100 480,160Z\" fill=\"#78716c\"/><text x=\"300\" y=\"200\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Corcovado and Christ the Redeemer</text><text x=\"470\" y=\"96\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sugarloaf Mountain</text><text x=\"130\" y=\"150\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Copacabana beach</text></svg>","c":"Rio’s mountains and bay (schematic)"}]},"atlantic":{"t":"The Atlantic Ocean","c":"The Atlantic is the second-largest ocean, covering about a fifth of Earth’s surface between the Americas, Europe and Africa. Down its middle runs the Mid-Atlantic Ridge, where tectonic plates pull apart and the ocean widens by a few centimetres a year. The Gulf Stream, a powerful warm current, carries heat from the Caribbean toward Europe, keeping countries such as Britain and Norway much milder than other places at the same latitude. The Atlantic was the main route of the Age of Exploration and the slave trade.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 104\" width=\"610\" height=\"104\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"190\" height=\"84\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Atlantic</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 106 million km²</text><text x=\"24\" y=\"74\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Second-largest ocean</text><rect x=\"210\" y=\"10\" width=\"190\" height=\"84\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"224\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mid-Atlantic Ridge</text><text x=\"224\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Underwater mountain chain</text><text x=\"224\" y=\"74\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Splits the ocean floor</text><rect x=\"410\" y=\"10\" width=\"190\" height=\"84\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"424\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Gulf Stream</text><text x=\"424\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Warm current</text><text x=\"424\" y=\"74\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Keeps western Europe mild</text></svg>","c":"Key features of the Atlantic"}]},"indocean":{"t":"The world’s oceans by size","c":"Earth has five oceans, all connected as one world ocean. The Pacific is by far the largest, bigger than all the land on Earth combined. The Indian Ocean, third-largest, lies between Africa, Asia and Australia and is the warmest ocean; its monsoon winds have shaped trade, farming and culture around its shores for thousands of years. The Southern Ocean around Antarctica was officially recognised by many geographers only recently. Areas are approximate.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 224\" width=\"620\" height=\"224\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"130\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Pacific</text><rect x=\"140\" y=\"12\" width=\"340.0\" height=\"28\" rx=\"5\" fill=\"#1d4ed8\"/><text x=\"488\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">165 million km²</text><text x=\"130\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Atlantic</text><rect x=\"140\" y=\"52\" width=\"218.4\" height=\"28\" rx=\"5\" fill=\"#2563eb\"/><text x=\"366.42424242424244\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">106 million km²</text><text x=\"130\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Indian</text><rect x=\"140\" y=\"92\" width=\"144.2\" height=\"28\" rx=\"5\" fill=\"#0891b2\"/><text x=\"292.24242424242425\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">70 million km²</text><text x=\"130\" y=\"151\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Southern</text><rect x=\"140\" y=\"132\" width=\"43.3\" height=\"28\" rx=\"5\" fill=\"#64748b\"/><text x=\"191.27272727272728\" y=\"151\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">21 million km²</text><text x=\"130\" y=\"191\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Arctic</text><rect x=\"140\" y=\"172\" width=\"30.9\" height=\"28\" rx=\"5\" fill=\"#bae6fd\"/><text x=\"178.9090909090909\" y=\"191\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">15 million km²</text></svg>","c":"Approximate areas of the five oceans"}]},"alps":{"t":"The Alps","c":"The Alps are Europe’s highest mountain range, arcing about 1,200 kilometres across France, Switzerland, Italy, Monaco, Liechtenstein, Austria, Germany and Slovenia. They formed as the African plate pushed into Europe, crumpling rock into folds. The highest peak, Mont Blanc, rises to about 4,806 metres. The Alps are a source of great rivers, including the Rhine, Rhône and Po, and a centre of skiing and mountaineering. Their glaciers have shrunk dramatically in recent decades as the climate warms. Schematic.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 230\" width=\"620\" height=\"230\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"230\" rx=\"10\" fill=\"#e0f2fe\"/><path d=\"M0,230L80,120L150,140L230,60L300,110L370,40L440,100L520,70L620,130V230Z\" fill=\"#78716c\"/><path d=\"M212,80L230,60L248,80Z M352,60L370,40L388,60Z M504,86L520,70L536,86Z\" fill=\"#f8fafc\"/><text x=\"370\" y=\"30\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mont Blanc, 4,806 m</text><text x=\"310\" y=\"215\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Spans 8 countries over about 1,200 km</text></svg>","c":"An alpine skyline (schematic)"}]},"rockies":{"t":"The Rocky Mountains","c":"The Rocky Mountains stretch about 4,800 kilometres from northern British Columbia in Canada to New Mexico in the United States. Their highest peak is Mount Elbert in Colorado, at about 4,401 metres. Along their crest runs the Continental Divide: rain falling on one side flows toward the Pacific, on the other toward the Atlantic or Arctic. The Rockies are home to bears, elk, bighorn sheep and wolves, and to famous national parks such as Yellowstone, Banff and Rocky Mountain. Schematic.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 230\" width=\"620\" height=\"230\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"230\" rx=\"10\" fill=\"#e0f2fe\"/><path d=\"M0,230L60,90L120,130L180,40L250,120L320,60L400,140L480,80L560,110L620,150V230Z\" fill=\"#78716c\"/><path d=\"M164,60L180,40L196,60Z M304,80L320,60L336,80Z\" fill=\"#f8fafc\"/><text x=\"320\" y=\"50\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mount Elbert, 4,401 m (highest)</text><text x=\"310\" y=\"215\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">About 4,800 km from Canada to New Mexico</text></svg>","c":"A Rocky Mountain skyline (schematic)"}]},"plateaus":{"t":"What a plateau is","c":"A plateau is a large area of high, fairly flat land, often bounded by steep slopes on at least one side. Some are raised by tectonic plates pushing together, others built up by layer upon layer of lava, and some are carved out as rivers cut deep valleys into surrounding land. The Tibetan Plateau, the highest and largest, averages around 4,500 metres and is called the Roof of the World. Others include the Deccan Plateau of India, the Colorado Plateau and the Bolivian Altiplano. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 210\" width=\"620\" height=\"210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"210\" rx=\"10\" fill=\"#e0f2fe\"/><path d=\"M0,210V170L100,170L140,60H480L520,170H620V210Z\" fill=\"#a16207\"/><text x=\"310\" y=\"100\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Plateau: a high, flat-topped area</text><text x=\"120\" y=\"150\" text-anchor=\"end\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Steep sides</text><text x=\"310\" y=\"195\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Tibetan Plateau averages about 4,500 m</text></svg>","c":"A simplified plateau"}]},"deforestation":{"t":"How a forest is cleared","c":"Deforestation is the permanent removal of forests, mostly to make room for farming, cattle ranching, plantations such as palm oil and soy, mining and roads. The world lost around 10 million hectares of forest a year in the late 2010s, mostly in the tropics, according to the UN. Clearing forests releases stored carbon, adding to climate change, destroys habitats for countless species and can disrupt rainfall and soils. Reforestation, protected areas and supply chains free of deforestation are among the responses. Simplified.","items":[{"s":"<svg viewBox=\"0 0 190 168\" width=\"190\" height=\"168\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:180px;max-width:100%;height:auto\"><rect width=\"190\" height=\"140\" rx=\"10\" fill=\"#ecfccb\"/><rect x=\"17\" y=\"60\" width=\"6\" height=\"20\" fill=\"#78350f\"/><circle cx=\"20\" cy=\"60\" r=\"14\" fill=\"#16a34a\"/><rect x=\"47\" y=\"80\" width=\"6\" height=\"20\" fill=\"#78350f\"/><circle cx=\"50\" cy=\"80\" r=\"14\" fill=\"#16a34a\"/><rect x=\"77\" y=\"60\" width=\"6\" height=\"20\" fill=\"#78350f\"/><circle cx=\"80\" cy=\"60\" r=\"14\" fill=\"#16a34a\"/><rect x=\"107\" y=\"80\" width=\"6\" height=\"20\" fill=\"#78350f\"/><circle cx=\"110\" cy=\"80\" r=\"14\" fill=\"#16a34a\"/><rect x=\"137\" y=\"60\" width=\"6\" height=\"20\" fill=\"#78350f\"/><circle cx=\"140\" cy=\"60\" r=\"14\" fill=\"#16a34a\"/><rect x=\"167\" y=\"80\" width=\"6\" height=\"20\" fill=\"#78350f\"/><circle cx=\"170\" cy=\"80\" r=\"14\" fill=\"#16a34a\"/><text x=\"95\" y=\"158\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1. Intact forest</text></svg>","c":""},{"s":"<svg viewBox=\"0 0 190 168\" width=\"190\" height=\"168\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:180px;max-width:100%;height:auto\"><rect width=\"190\" height=\"140\" rx=\"10\" fill=\"#ecfccb\"/><rect x=\"17\" y=\"60\" width=\"6\" height=\"20\" fill=\"#78350f\"/><circle cx=\"20\" cy=\"60\" r=\"14\" fill=\"#16a34a\"/><rect x=\"47\" y=\"80\" width=\"6\" height=\"20\" fill=\"#78350f\"/><circle cx=\"50\" cy=\"80\" r=\"14\" fill=\"#16a34a\"/><rect x=\"137\" y=\"60\" width=\"6\" height=\"20\" fill=\"#78350f\"/><circle cx=\"140\" cy=\"60\" r=\"14\" fill=\"#16a34a\"/><rect x=\"167\" y=\"80\" width=\"6\" height=\"20\" fill=\"#78350f\"/><circle cx=\"170\" cy=\"80\" r=\"14\" fill=\"#16a34a\"/><path d=\"M60,140L120,20\" stroke=\"#a16207\" stroke-width=\"10\"/><text x=\"95\" y=\"158\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2. Roads and logging</text></svg>","c":""},{"s":"<svg viewBox=\"0 0 190 168\" width=\"190\" height=\"168\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:180px;max-width:100%;height:auto\"><rect width=\"190\" height=\"140\" rx=\"10\" fill=\"#ecfccb\"/><rect x=\"10\" y=\"50\" width=\"170\" height=\"80\" fill=\"#fde68a\"/><path d=\"M10,60H180\" stroke=\"#ca8a04\"/><path d=\"M10,78H180\" stroke=\"#ca8a04\"/><path d=\"M10,96H180\" stroke=\"#ca8a04\"/><path d=\"M10,114H180\" stroke=\"#ca8a04\"/><text x=\"95\" y=\"158\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">3. Farmland</text></svg>","c":""}]},"conservation":{"t":"Ways to protect nature","c":"Conservation aims to protect species, habitats and ecosystems from being lost. Around 17 percent of the world’s land and 8 percent of its oceans are now in protected areas, and in 2022 nearly 200 countries agreed to try to protect 30 percent of each by 2030. Other approaches include restoring damaged habitats, breeding endangered animals for release, laws against poaching and trade in wildlife such as CITES, and working with local and Indigenous communities, who manage much of the world’s remaining wild land.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 170\" width=\"610\" height=\"170\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Protected areas</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">National parks and reserves</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#65a30d\" fill-opacity=\".2\" stroke=\"#65a30d\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Restoration</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Replanting forests, reviving wetlands</text><rect x=\"10\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"118\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Captive breeding</text><text x=\"24\" y=\"138\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Zoos help endangered species</text><rect x=\"310\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"324\" y=\"118\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Laws and trade bans</text><text x=\"324\" y=\"138\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Stopping poaching and smuggling</text></svg>","c":"Some of the main conservation tools"}]},"disasterprep":{"t":"Getting ready for a disaster","c":"Natural hazards such as earthquakes, typhoons, floods and wildfires cannot be prevented, but preparing can save lives. Emergency agencies advise every household to have a plan, know local warning signs and evacuation routes, and keep a go-bag with water, food, a torch, batteries, medicines, copies of documents and a first-aid kit, enough for at least three days. During an earthquake, the advice in many places is to drop, cover and hold on. Always follow instructions from local authorities. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 600 232\" width=\"600\" height=\"232\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"580\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Before</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Make a plan; prepare a go-bag; know evacuation routes</text><rect x=\"10\" y=\"84\" width=\"580\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">During</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Follow official warnings; get to safety</text><rect x=\"10\" y=\"158\" width=\"580\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">After</text><text x=\"24\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Check on others; avoid floodwater and damaged buildings</text></svg>","c":"Key actions before, during and after a disaster"}]},"foodsafety":{"t":"Four steps to food safety","c":"Food can carry bacteria, viruses and parasites that cause illness, which affects hundreds of millions of people a year worldwide. Health agencies teach four simple steps. Clean hands, utensils and surfaces. Separate raw meat, poultry and seafood from foods that will not be cooked. Cook food thoroughly, especially meat, to kill germs. Chill leftovers and perishable food quickly, since bacteria multiply fastest between about 5 °C and 60 °C, the temperature danger zone. The World Health Organization teaches a similar five-key version.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 170\" width=\"610\" height=\"170\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Clean</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wash hands and surfaces often</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Separate</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Keep raw meat away from ready-to-eat food</text><rect x=\"10\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#f97316\" fill-opacity=\".2\" stroke=\"#f97316\"/><text x=\"24\" y=\"118\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cook</text><text x=\"24\" y=\"138\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cook to safe temperatures</text><rect x=\"310\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#0891b2\" fill-opacity=\".2\" stroke=\"#0891b2\"/><text x=\"324\" y=\"118\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Chill</text><text x=\"324\" y=\"138\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Refrigerate promptly, below 5 °C</text></svg>","c":"Clean, separate, cook, chill"}]},"screentime":{"t":"The 20-20-20 rule for tired eyes","c":"Looking at screens for long periods can cause eye strain, dry eyes and headaches, partly because we blink less while concentrating. Eye doctors often recommend the 20-20-20 rule: every 20 minutes, look at something about 20 feet, or 6 metres, away for at least 20 seconds. Screens in bedrooms and late-night use can also disturb sleep. Health groups advise limits for young children and screen-free times, such as meals and the hour before bed, while recognising screens can also be used for learning and connection.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 90\" width=\"610\" height=\"90\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"190\" height=\"70\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">20</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Every 20 minutes</text><rect x=\"210\" y=\"10\" width=\"190\" height=\"70\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"224\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">20</text><text x=\"224\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">look at something 20 feet away</text><rect x=\"410\" y=\"10\" width=\"190\" height=\"70\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"424\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">20</text><text x=\"424\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">for 20 seconds</text></svg>","c":"An easy habit to rest the eyes"}]},"psychology":{"t":"Branches of psychology","c":"Psychology is the scientific study of the mind and behaviour. Psychologists ask how we perceive, think, feel, learn, remember and relate to others, and why people differ. Different branches take different approaches: biological psychology studies the brain and body, cognitive psychology studies mental processes, social psychology looks at how groups and others shape us, developmental psychology follows change from infancy to old age, and clinical psychology helps people with mental health problems. Wilhelm Wundt opened the first psychology laboratory in 1879.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 232\" width=\"610\" height=\"232\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Biological</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Brain, genes, hormones</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cognitive</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Thinking, memory, perception</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Behavioural</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Learning through rewards</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Social</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">How others influence us</text><rect x=\"10\" y=\"158\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"24\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Developmental</text><text x=\"24\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Change across life</text><rect x=\"310\" y=\"158\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#0891b2\" fill-opacity=\".2\" stroke=\"#0891b2\"/><text x=\"324\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Clinical</text><text x=\"324\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Understanding and treating mental illness</text></svg>","c":"Six major branches"}]},"anthropology":{"t":"The four fields of anthropology","c":"Anthropology is the study of humans, past and present, in all their diversity. In many countries it is divided into four fields: cultural anthropology studies living societies, often through fieldwork in which researchers live among the people they study; biological anthropology studies human evolution, genetics and variation; linguistic anthropology studies language in social life; and archaeology studies past societies through the objects they left. Anthropologists aim to understand other ways of life on their own terms.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cultural</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Customs, beliefs, ways of life</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Biological</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Human evolution and variation</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Linguistic</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Language and society</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Archaeology</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Past peoples through objects</text></svg>","c":"The four traditional fields"}]},"byzant":{"t":"The Byzantine Empire","c":"The Byzantine Empire was the eastern half of the Roman Empire, which survived for nearly a thousand years after the western half fell in 476. Its capital, Constantinople, founded by Emperor Constantine in 330, was for centuries the largest and richest city in Europe. The Byzantines called themselves Romans, spoke Greek, preserved classical learning and developed Orthodox Christianity. The great church of Hagia Sophia, built under Justinian, was the largest in the world for centuries. The empire ended when the Ottomans captured Constantinople in 1453.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">330</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Constantine founds Constantinople</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">527–565</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Justinian’s reign; Hagia Sophia built</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1054</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Split between Eastern and Western churches</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1204</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Crusaders sack Constantinople</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1453</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Ottomans capture Constantinople</text></svg>","c":"Milestones of the Byzantine Empire"}]},"crusades":{"t":"The Crusades","c":"The Crusades were a series of religious wars from 1095 to 1291 in which Christian armies from Western Europe tried to take control of Jerusalem and the Holy Land from Muslim rulers. The First Crusade captured Jerusalem in 1099, with great slaughter, but the Muslim leader Saladin retook it in 1187. Later crusades largely failed, and the Fourth even sacked Christian Constantinople. The wars brought violence against Muslims, Jews and Eastern Christians but also increased trade and the exchange of goods and ideas between Europe and the Middle East.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#b91c1c\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1095</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Pope Urban II calls the First Crusade</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#b91c1c\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1099</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Crusaders capture Jerusalem</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#b91c1c\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1187</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Saladin retakes Jerusalem</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#b91c1c\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1204</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Fourth Crusade sacks Constantinople</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#b91c1c\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1291</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Last crusader stronghold, Acre, falls</text></svg>","c":"Key events of the Crusades"}]},"koreanwar":{"t":"The Korean War","c":"After the Second World War, Korea was divided at the 38th parallel into a Soviet-backed North and an American-backed South. In June 1950 North Korea invaded the South. A United Nations force led by the United States pushed the North back, then China joined on the North’s side. After three years of fighting, and millions of deaths, mostly civilians, an armistice in 1953 left the border near where it began, with a heavily guarded demilitarised zone. No peace treaty was ever signed, so the two Koreas technically remain at war.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#334155\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">June 1950</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">North Korea invades the South</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#334155\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sept 1950</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">UN forces land at Inchon</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#334155\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Oct 1950</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">China enters the war</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#334155\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1951–53</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Fighting stalls near the 38th parallel</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#334155\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">July 1953</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Armistice signed; no peace treaty</text></svg>","c":"Key events of the war"}]},"persia":{"t":"The Persian Empire","c":"The Achaemenid Persian Empire, founded by Cyrus the Great around 550 BC in what is now Iran, became the largest empire the world had yet seen, stretching from Egypt and the Balkans to the Indus Valley. Cyrus was known for allowing conquered peoples to keep their customs and religions. Darius I organised the empire into provinces, built the Royal Road with relay stations for messengers, standardised coins and built the palace of Persepolis. The empire fell to Alexander the Great in 330 BC, but later Persian empires rose after it.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 204\" width=\"640\" height=\"204\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"188\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">550 BC</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cyrus the Great founds the Achaemenid Empire</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">522–486 BC</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Darius I builds roads and Persepolis</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">480 BC</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Xerxes invades Greece</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">330 BC</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Conquered by Alexander the Great</text></svg>","c":"Milestones of the Achaemenid Empire"}]},"mali":{"t":"Gold for salt in the Mali Empire","c":"The Mali Empire, founded by Sundiata Keita around 1235, controlled much of West Africa and grew rich from trans-Saharan trade, especially exchanging gold from the south for salt from mines in the Sahara, carried by camel caravans. Its cities, such as Timbuktu, became great centres of Islamic learning, with libraries holding thousands of manuscripts. Its most famous ruler, Mansa Musa, made a pilgrimage to Mecca in 1324 with such lavish spending of gold that he reportedly caused prices to fall in Cairo. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#fef3c7\"/><rect x=\"20\" y=\"60\" width=\"170\" height=\"80\" rx=\"10\" fill=\"#facc15\"/><text x=\"105\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Gold from the south</text><text x=\"105\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">mines of West Africa</text><path d=\"M190,100H222\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M230,100l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"230\" y=\"60\" width=\"160\" height=\"80\" rx=\"10\" fill=\"#fde68a\"/><text x=\"310\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Mali’s cities</text><text x=\"310\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">Timbuktu, Djenné</text><path d=\"M430,100H398\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M390,100l10,-6v12z\" fill=\"currentColor\"/><rect x=\"430\" y=\"60\" width=\"170\" height=\"80\" rx=\"10\" fill=\"#e7e5e4\"/><text x=\"515\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Salt from the north</text><text x=\"515\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">Saharan mines</text></svg>","c":"The gold–salt trade at the heart of Mali’s wealth"}]},"opium":{"t":"The Opium Wars","c":"In the early 1800s British merchants sold large amounts of opium, grown in British India, into China to pay for Chinese tea, silk and porcelain, causing widespread addiction. When China’s Qing government seized and destroyed opium stocks in 1839, Britain went to war. China’s defeats in the First and Second Opium Wars forced it to open ports, pay compensation, legalise opium and hand Hong Kong to Britain, beginning what Chinese historians call the ‘century of humiliation’. Hong Kong was returned to China in 1997.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 204\" width=\"640\" height=\"204\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"188\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#7c2d12\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1839–42</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">First Opium War</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#7c2d12\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1842</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Treaty of Nanjing; Hong Kong ceded to Britain</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#7c2d12\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1856–60</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Second Opium War</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#7c2d12\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1997</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Hong Kong returned to China</text></svg>","c":"Key events"}]},"africacolon":{"t":"The colonisation of Africa","c":"In 1870 European powers controlled about a tenth of Africa, mostly along the coasts. In the ‘Scramble for Africa’ that followed, and after the Berlin Conference of 1884–85, Britain, France, Germany, Belgium, Portugal, Italy and Spain divided almost the whole continent among themselves within about 30 years, often drawing borders with little regard for the peoples living there. By 1914 only Ethiopia and Liberia remained independent. Colonial rule brought exploitation and violence. Most African countries regained independence between the late 1950s and the 1970s.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1884–85</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Berlin Conference sets rules for claiming Africa</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1914</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Most of Africa under European rule</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1957</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Ghana gains independence</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1960</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Year of Africa: 17 nations independent</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1994</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">End of apartheid in South Africa</text></svg>","c":"From colonisation to independence"}]},"modernchina":{"t":"China since 1949","c":"The Chinese Communist Party, led by Mao Zedong, founded the People’s Republic of China in 1949 after a long civil war. Mao’s campaigns, including the Great Leap Forward, which caused one of history’s deadliest famines, and the Cultural Revolution, brought immense suffering. From 1978, Deng Xiaoping introduced market reforms that sparked decades of rapid growth, lifting hundreds of millions of people out of poverty and making China the world’s second-largest economy. China remains a one-party state.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 288\" width=\"640\" height=\"288\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"272\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1949</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">People’s Republic of China founded</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1958–62</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Great Leap Forward; tens of millions die in famine</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1966–76</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cultural Revolution</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1978</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Deng Xiaoping begins economic reforms</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2001</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">China joins the World Trade Organization</text><circle cx=\"140\" cy=\"244\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"249\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2010</text><text x=\"156\" y=\"249\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Becomes world’s second-largest economy</text></svg>","c":"Key moments since 1949"}]},"greenrev":{"t":"The Green Revolution","c":"From the 1940s to the 1970s, scientists developed high-yielding varieties of wheat and rice that, with fertiliser, irrigation and pesticides, produced far more grain per hectare. Led by researchers such as Norman Borlaug, who won the Nobel Peace Prize in 1970, and institutes such as the International Rice Research Institute in the Philippines, the Green Revolution greatly increased harvests in Mexico, India, Pakistan and much of Asia, helping prevent famines. It also brought problems, including heavy chemical use, falling groundwater and benefits that favoured wealthier farmers.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 184\" width=\"620\" height=\"184\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"100\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1961</text><rect x=\"110\" y=\"12\" width=\"152.8\" height=\"28\" rx=\"5\" fill=\"#a3e635\"/><text x=\"270.82608695652175\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 1.9 t per hectare</text><text x=\"100\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1980</text><rect x=\"110\" y=\"52\" width=\"217.2\" height=\"28\" rx=\"5\" fill=\"#84cc16\"/><text x=\"335.1739130434783\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 2.7 t</text><text x=\"100\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2000</text><rect x=\"110\" y=\"92\" width=\"313.7\" height=\"28\" rx=\"5\" fill=\"#65a30d\"/><text x=\"431.69565217391306\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 3.9 t</text><text x=\"100\" y=\"151\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2020</text><rect x=\"110\" y=\"132\" width=\"370.0\" height=\"28\" rx=\"5\" fill=\"#4d7c0f\"/><text x=\"488\" y=\"151\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 4.6 t</text></svg>","c":"Approximate average world cereal yield"}]},"oxygen":{"t":"Oxygen: the breath of life","c":"Oxygen makes up about 21 percent of the air and is the most abundant element in Earth’s crust, locked in rocks and water. Almost all of the oxygen in the air was produced by photosynthesis, first by ancient ocean microbes from about 2.4 billion years ago and later by plants and algae. Animals, including us, breathe it in to release energy from food, breathing out carbon dioxide that plants use again. Oxygen was discovered in the 1770s by Carl Scheele and Joseph Priestley, and named by Antoine Lavoisier.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 210\" width=\"620\" height=\"210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"210\" rx=\"10\" fill=\"#f8fafc\"/><rect x=\"20\" y=\"70\" width=\"170\" height=\"70\" rx=\"10\" fill=\"#e0e7ff\"/><text x=\"105\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Plants make oxygen</text><text x=\"105\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">by photosynthesis</text><path d=\"M190,105H222\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M230,105l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"230\" y=\"70\" width=\"160\" height=\"70\" rx=\"10\" fill=\"#bae6fd\"/><text x=\"310\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Air</text><text x=\"310\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">about 21% oxygen</text><path d=\"M390,105H422\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M430,105l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"430\" y=\"70\" width=\"170\" height=\"70\" rx=\"10\" fill=\"#fecaca\"/><text x=\"515\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Animals breathe it</text><text x=\"515\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">to release energy from food</text></svg>","c":"The oxygen cycle, simplified"}]},"carbonchem":{"t":"One element, many forms","c":"Carbon atoms can bond with up to four other atoms, including other carbon atoms, in chains, rings and sheets, which is why carbon forms millions of compounds and is the basis of all known life. Pure carbon alone comes in very different forms: in diamond, every atom is locked in a rigid 3D lattice, making it extremely hard; in graphite, atoms form flat sheets that slide over each other, which is why pencils work; and graphene, a single sheet of graphite, is one of the strongest materials known.","items":[{"w":1,"s":"<svg viewBox=\"0 0 600 214\" width=\"600\" height=\"214\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"580\" height=\"58\" rx=\"10\" fill=\"#38bdf8\" fill-opacity=\".2\" stroke=\"#38bdf8\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Diamond</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Carbon atoms in a rigid 3D lattice: the hardest natural material</text><rect x=\"10\" y=\"78\" width=\"580\" height=\"58\" rx=\"10\" fill=\"#475569\" fill-opacity=\".2\" stroke=\"#475569\"/><text x=\"24\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Graphite</text><text x=\"24\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Flat sheets that slide: pencil ‘lead’</text><rect x=\"10\" y=\"146\" width=\"580\" height=\"58\" rx=\"10\" fill=\"#94a3b8\" fill-opacity=\".2\" stroke=\"#94a3b8\"/><text x=\"24\" y=\"174\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Graphene</text><text x=\"24\" y=\"194\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">A single sheet one atom thick: very strong</text></svg>","c":"Three forms of pure carbon"}]},"nobel":{"t":"The Nobel Prize categories","c":"The Nobel Prizes were established by the will of Alfred Nobel, the Swedish chemist who invented dynamite, and first awarded in 1901. Prizes are given each year in physics, chemistry, physiology or medicine, literature and peace; a prize in economic sciences was added in 1969 by Sweden’s central bank. The peace prize is awarded in Oslo, Norway, and the others in Stockholm, Sweden. Winners receive a medal, a diploma and a share of about 11 million Swedish kronor. Marie Curie was the first woman to win, in 1903.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 178\" width=\"610\" height=\"178\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"46\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Physics</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"310\" y=\"10\" width=\"290\" height=\"46\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Chemistry</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"10\" y=\"66\" width=\"290\" height=\"46\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"94\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Physiology or Medicine</text><text x=\"24\" y=\"114\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"310\" y=\"66\" width=\"290\" height=\"46\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"94\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Literature</text><text x=\"324\" y=\"114\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"10\" y=\"122\" width=\"290\" height=\"46\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"24\" y=\"150\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Peace</text><text x=\"24\" y=\"170\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"310\" y=\"122\" width=\"290\" height=\"46\" rx=\"10\" fill=\"#64748b\" fill-opacity=\".2\" stroke=\"#64748b\"/><text x=\"324\" y=\"150\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Economic Sciences (from 1969)</text><text x=\"324\" y=\"170\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text></svg>","c":"The six prize categories"}]},"accelerators":{"t":"The Large Hadron Collider","c":"Particle accelerators speed up subatomic particles to nearly the speed of light and smash them together, letting physicists study the smallest building blocks of matter. The largest, CERN’s Large Hadron Collider near Geneva, is a ring 27 kilometres around, buried about 100 metres underground across the French–Swiss border. Its superconducting magnets are cooled to −271 °C, colder than outer space. In 2012 it discovered the Higgs boson. Smaller accelerators are used in hospitals to treat cancer and in industry. Figures are approximate.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 144\" width=\"620\" height=\"144\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"190\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">LHC ring</text><rect x=\"200\" y=\"12\" width=\"280.0\" height=\"28\" rx=\"5\" fill=\"#2563eb\"/><text x=\"488\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">27 km around</text><text x=\"190\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tevatron (US, closed)</text><rect x=\"200\" y=\"52\" width=\"65.3\" height=\"28\" rx=\"5\" fill=\"#64748b\"/><text x=\"273.3333333333333\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">6.3 km</text><text x=\"190\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Distance across Paris</text><rect x=\"200\" y=\"92\" width=\"103.7\" height=\"28\" rx=\"5\" fill=\"#94a3b8\"/><text x=\"311.7037037037037\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 10 km, for comparison</text></svg>","c":"How big the Large Hadron Collider is"}]},"neutrinos":{"t":"Ghostly neutrinos","c":"Neutrinos are tiny particles with no electric charge and almost no mass, produced in huge numbers by nuclear reactions in the Sun, in supernovae and in nuclear reactors. They interact so weakly with matter that most pass straight through the entire Earth without hitting anything; about 100 billion from the Sun pass through each square centimetre of your body every second. Detecting them requires enormous underground tanks of water or ice, such as IceCube at the South Pole. The discovery that they change type and have mass won the 2015 Nobel Prize. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#0b1026\"/><circle cx=\"80\" cy=\"100\" r=\"40\" fill=\"#facc15\"/><path d=\"M120,80L590,60\" stroke=\"#a78bfa\" stroke-width=\"1\" opacity=\".6\"/><path d=\"M120,88L590,76\" stroke=\"#a78bfa\" stroke-width=\"1\" opacity=\".6\"/><path d=\"M120,96L590,92\" stroke=\"#a78bfa\" stroke-width=\"1\" opacity=\".6\"/><path d=\"M120,104L590,108\" stroke=\"#a78bfa\" stroke-width=\"1\" opacity=\".6\"/><path d=\"M120,112L590,124\" stroke=\"#a78bfa\" stroke-width=\"1\" opacity=\".6\"/><path d=\"M120,120L590,140\" stroke=\"#a78bfa\" stroke-width=\"1\" opacity=\".6\"/><circle cx=\"300\" cy=\"100\" r=\"30\" fill=\"#60a5fa\"/><text x=\"340\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#e2e8f0\" font-family=\"system-ui,sans-serif\">Trillions pass through your body every second</text><text x=\"300\" y=\"150\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#e2e8f0\" font-family=\"system-ui,sans-serif\">Earth</text><text x=\"80\" y=\"160\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#e2e8f0\" font-family=\"system-ui,sans-serif\">Sun</text><text x=\"470\" y=\"180\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#c4b5fd\" font-family=\"system-ui,sans-serif\">Neutrinos fly straight through</text></svg>","c":"Neutrinos streaming from the Sun through Earth"}]},"dreams":{"t":"The stages of sleep","c":"Sleep is not a single state but cycles through stages about every 90 minutes. Light sleep leads into deeper sleep, when the body repairs itself and the brain consolidates memories, and then rapid eye movement, or REM, sleep, when the brain is very active and most vivid dreams happen, while the body is temporarily paralysed so we do not act them out. REM periods grow longer toward morning. Why we dream is still debated; ideas include processing emotions, strengthening memories and rehearsing responses to threats. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#f8fafc\"/><rect x=\"20\" y=\"130\" width=\"130\" height=\"40\" rx=\"6\" fill=\"#bfdbfe\"/><text x=\"85\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Stage 1</text><text x=\"85\" y=\"48\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">light sleep</text><rect x=\"165\" y=\"90\" width=\"130\" height=\"80\" rx=\"6\" fill=\"#93c5fd\"/><text x=\"230\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Stage 2</text><text x=\"230\" y=\"48\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">heart rate slows</text><rect x=\"310\" y=\"50\" width=\"130\" height=\"120\" rx=\"6\" fill=\"#2563eb\"/><text x=\"375\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Stage 3</text><text x=\"375\" y=\"48\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">deep sleep</text><rect x=\"455\" y=\"110\" width=\"130\" height=\"60\" rx=\"6\" fill=\"#7c3aed\"/><text x=\"520\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">REM</text><text x=\"520\" y=\"48\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">vivid dreams</text><text x=\"310\" y=\"192\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">One sleep cycle lasts about 90 minutes; most people have 4–6 a night</text></svg>","c":"The stages of one sleep cycle (bar height suggests depth)"}]},"ecommerce":{"t":"From click to doorstep","c":"Online shopping, or e-commerce, has grown enormously since the 1990s, and especially during the COVID-19 pandemic. When you order, the store’s systems process payment, a fulfilment warehouse, often heavily automated with robots, picks and packs the item, and delivery companies carry it through sorting hubs to your door or a pickup locker, sometimes the same day. E-commerce now makes up roughly a fifth of global retail sales. It brings convenience and choice but also raises concerns about packaging waste, delivery emissions and pressure on workers. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 180\" width=\"620\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"210\" rx=\"10\" fill=\"#f8fafc\"/><rect x=\"20\" y=\"70\" width=\"140\" height=\"70\" rx=\"10\" fill=\"#fde68a\"/><text x=\"90\" y=\"110\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">You buy online</text><path d=\"M160,105H182\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M190,105l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"190\" y=\"70\" width=\"120\" height=\"70\" rx=\"10\" fill=\"#bfdbfe\"/><text x=\"250\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Warehouse</text><text x=\"250\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">picks and packs</text><path d=\"M310,105H332\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M340,105l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"340\" y=\"70\" width=\"120\" height=\"70\" rx=\"10\" fill=\"#c7d2fe\"/><text x=\"400\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Delivery</text><text x=\"400\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">van, bike, drone</text><path d=\"M460,105H482\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M490,105l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"490\" y=\"70\" width=\"120\" height=\"70\" rx=\"10\" fill=\"#bbf7d0\"/><text x=\"550\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Your door</text><text x=\"550\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">or a locker</text></svg>","c":"The journey of an online order"}]},"digitalpay":{"t":"How a digital payment works","c":"Digital payments let people pay with phones, cards and apps instead of cash. When you scan a QR code or tap your phone, a payment app or card network checks your identity and balance, then instructs banks to move money to the seller, usually within seconds. Countries such as India, with its UPI system, China, with Alipay and WeChat Pay, Kenya, with M-Pesa, and Sweden have become largely cashless in everyday shopping. Digital payments are convenient and can include people without bank accounts, but raise questions about privacy, scams and those without phones. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 180\" width=\"620\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"210\" rx=\"10\" fill=\"#f8fafc\"/><rect x=\"20\" y=\"70\" width=\"140\" height=\"70\" rx=\"10\" fill=\"#bfdbfe\"/><text x=\"90\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Your phone</text><text x=\"90\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">scan or tap</text><path d=\"M160,105H182\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M190,105l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"190\" y=\"70\" width=\"130\" height=\"70\" rx=\"10\" fill=\"#fde68a\"/><text x=\"255\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Payment app</text><text x=\"255\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">checks and confirms</text><path d=\"M320,105H342\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M350,105l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"350\" y=\"70\" width=\"120\" height=\"70\" rx=\"10\" fill=\"#c7d2fe\"/><text x=\"410\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Banks</text><text x=\"410\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">move the money</text><path d=\"M470,105H492\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M500,105l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"500\" y=\"70\" width=\"110\" height=\"70\" rx=\"10\" fill=\"#bbf7d0\"/><text x=\"555\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Seller</text><text x=\"555\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">paid in seconds</text></svg>","c":"The steps behind a phone payment"}]},"covid19":{"t":"The COVID-19 pandemic","c":"COVID-19, caused by the SARS-CoV-2 coronavirus, was first identified in Wuhan, China, in late 2019 and spread worldwide within months. Governments closed borders, schools and businesses, and billions of people lived under lockdowns. Vaccines were developed in under a year, some using new mRNA technology, and over 13 billion doses were given. The World Health Organization estimated that the pandemic caused around 7 million reported deaths, with the true toll several times higher. It ended as a global emergency in May 2023.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dec 2019</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">First cases identified in Wuhan, China</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mar 2020</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">WHO declares a pandemic; lockdowns worldwide</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dec 2020</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">First vaccines approved and rolled out</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2021–22</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Delta and Omicron variants spread</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">May 2023</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">WHO ends the global health emergency</text></svg>","c":"Key moments of the pandemic"}]},"vaping":{"t":"What is known about vaping","c":"E-cigarettes heat a liquid, usually containing nicotine and flavourings, into an aerosol that users inhale. Health authorities generally agree they are less harmful than smoking tobacco cigarettes and may help some adult smokers quit, but they are not harmless: nicotine is highly addictive and can harm the developing brains of teenagers, and the aerosol can contain harmful substances. Their long-term effects are still unknown. Youth vaping rose sharply in many countries, and governments have responded with age limits, flavour bans and taxes.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 170\" width=\"610\" height=\"170\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Nicotine</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Highly addictive; harms teen brains</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Lung irritation</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Aerosol can carry harmful chemicals</text><rect x=\"10\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"118\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Lower risk than smoking</text><text x=\"24\" y=\"138\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">For adult smokers who switch completely</text><rect x=\"310\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#64748b\" fill-opacity=\".2\" stroke=\"#64748b\"/><text x=\"324\" y=\"118\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Unknown long-term effects</text><text x=\"324\" y=\"138\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Still being studied</text></svg>","c":"Main points health authorities make"}]},"nato":{"t":"NATO’s growth","c":"The North Atlantic Treaty Organization was founded in 1949 by the United States, Canada and ten Western European countries as a military alliance against the Soviet Union. Its core principle, Article 5, says an attack on one member is an attack on all; it has been invoked only once, after the 11 September 2001 attacks on the United States. After the Cold War, many former Eastern Bloc countries joined, and Finland and Sweden joined in 2023 and 2024 after Russia’s full-scale invasion of Ukraine, bringing membership to 32.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1949</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">12 founding members</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1952</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Greece and Turkey join</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1955</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">West Germany joins</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1999–2004</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Former Eastern Bloc countries join</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2023–24</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Finland and Sweden join (32 members)</text></svg>","c":"Milestones in NATO membership"}]},"education":{"t":"The stages of education","c":"Most education systems move through stages. Early childhood education prepares young children for school. Primary school teaches basic literacy, numeracy and other subjects; secondary school deepens these, often ending in exams or a diploma; and tertiary education includes universities, colleges and vocational training. Ages and names differ between countries. Around 250 million children and young people worldwide are still out of school, according to UNESCO, mostly in poorer and conflict-affected regions.","items":[{"w":1,"s":"<svg viewBox=\"0 0 600 220\" width=\"600\" height=\"220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"580\" height=\"60\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Primary</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">About ages 6–11: reading, writing, maths</text><rect x=\"10\" y=\"80\" width=\"580\" height=\"60\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"108\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Secondary</text><text x=\"24\" y=\"128\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">About ages 12–17: subjects and exams</text><rect x=\"10\" y=\"150\" width=\"580\" height=\"60\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"24\" y=\"178\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tertiary</text><text x=\"24\" y=\"198\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">University, college, vocational training</text></svg>","c":"Common stages of schooling"}]},"clothing":{"t":"Common fabric fibres","c":"Clothing is made from natural or synthetic fibres spun into yarn and woven or knitted into fabric. Natural fibres come from plants, such as cotton, linen and hemp, or animals, such as wool and silk. Synthetic fibres such as polyester and nylon, first developed in the 20th century, are made from chemicals derived mostly from oil and now account for over half of all fibre produced. Each has trade-offs in comfort, durability, cost and environmental impact, from the water used to grow cotton to the microplastics shed by synthetics.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 220\" width=\"610\" height=\"220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"60\" rx=\"10\" fill=\"#94a3b8\" fill-opacity=\".2\" stroke=\"#94a3b8\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cotton</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Plant fibre; soft and breathable</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"60\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wool</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Animal fibre; warm</text><rect x=\"10\" y=\"80\" width=\"290\" height=\"60\" rx=\"10\" fill=\"#db2777\" fill-opacity=\".2\" stroke=\"#db2777\"/><text x=\"24\" y=\"108\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Silk</text><text x=\"24\" y=\"128\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">From silkworms; smooth</text><rect x=\"310\" y=\"80\" width=\"290\" height=\"60\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"324\" y=\"108\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Polyester</text><text x=\"324\" y=\"128\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Made from oil; tough and cheap</text><rect x=\"10\" y=\"150\" width=\"290\" height=\"60\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"24\" y=\"178\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Linen</text><text x=\"24\" y=\"198\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">From flax; cool</text><rect x=\"310\" y=\"150\" width=\"290\" height=\"60\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"178\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Nylon</text><text x=\"324\" y=\"198\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Synthetic; strong and stretchy</text></svg>","c":"Six common fibres and their traits"}]},"amazonriver":{"t":"The Amazon carries the most water","c":"The Amazon is the largest river in the world by the amount of water it carries, discharging on average about 200,000 cubic metres every second into the Atlantic, roughly a fifth of all the fresh water that rivers deliver to the oceans and more than the next several largest rivers combined. Its basin, covering about 7 million square kilometres across nine South American countries, holds the largest rainforest on Earth. Whether it or the Nile is the longest river depends on how lengths are measured. Figures are approximate average discharges.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 264\" width=\"620\" height=\"264\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"180\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Amazon</text><rect x=\"190\" y=\"12\" width=\"280.0\" height=\"28\" rx=\"5\" fill=\"#16a34a\"/><text x=\"478\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 209,000 m³/s</text><text x=\"180\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Congo</text><rect x=\"190\" y=\"52\" width=\"54.9\" height=\"28\" rx=\"5\" fill=\"#a16207\"/><text x=\"252.92822966507177\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 41,000</text><text x=\"180\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Ganges–Brahmaputra</text><rect x=\"190\" y=\"92\" width=\"50.9\" height=\"28\" rx=\"5\" fill=\"#f59e0b\"/><text x=\"248.9090909090909\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 38,000</text><text x=\"180\" y=\"151\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Orinoco</text><rect x=\"190\" y=\"132\" width=\"49.6\" height=\"28\" rx=\"5\" fill=\"#0891b2\"/><text x=\"247.5693779904306\" y=\"151\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 37,000</text><text x=\"180\" y=\"191\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Yangtze</text><rect x=\"190\" y=\"172\" width=\"41.5\" height=\"28\" rx=\"5\" fill=\"#2563eb\"/><text x=\"239.5311004784689\" y=\"191\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 31,000</text><text x=\"180\" y=\"231\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Nile</text><rect x=\"190\" y=\"212\" width=\"4.0\" height=\"28\" rx=\"5\" fill=\"#94a3b8\"/><text x=\"202\" y=\"231\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 2,800</text></svg>","c":"Approximate average water flow at the river mouth"}]},"yangtze":{"t":"The Yangtze from source to sea","c":"The Yangtze, about 6,300 kilometres long, is the longest river in Asia and the third-longest in the world. It rises on the Tibetan Plateau and flows east across China to reach the East China Sea at Shanghai. Its basin is home to roughly a third of China’s population and produces much of its rice. The Three Gorges Dam, completed in 2006, is the world’s largest power station by capacity, though its construction displaced over a million people. Schematic, not a map.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#e0f2fe\"/><path d=\"M20,30Q180,60 260,100T600,170\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"12\"/><circle cx=\"30\" cy=\"30\" r=\"8\" fill=\"#f59e0b\" stroke=\"#fff\" stroke-width=\"2\"/><text x=\"30\" y=\"16\" text-anchor=\"start\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tibetan Plateau</text><circle cx=\"260\" cy=\"100\" r=\"8\" fill=\"#f59e0b\" stroke=\"#fff\" stroke-width=\"2\"/><text x=\"260\" y=\"86\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Three Gorges Dam</text><circle cx=\"380\" cy=\"130\" r=\"8\" fill=\"#f59e0b\" stroke=\"#fff\" stroke-width=\"2\"/><text x=\"380\" y=\"116\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wuhan</text><circle cx=\"590\" cy=\"168\" r=\"8\" fill=\"#f59e0b\" stroke=\"#fff\" stroke-width=\"2\"/><text x=\"590\" y=\"154\" text-anchor=\"end\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Shanghai</text><text x=\"310\" y=\"192\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">About 6,300 km long: Asia’s longest river</text></svg>","c":"The Yangtze’s course (schematic)"}]},"ganges":{"t":"The Ganges","c":"The Ganges, or Ganga, flows about 2,500 kilometres from the Gangotri Glacier in the Himalayas across northern India to the Bay of Bengal, where, joined by the Brahmaputra, it forms the world’s largest delta in Bangladesh and India. The river is sacred in Hinduism, and millions bathe in it at holy cities such as Varanasi and at the Kumbh Mela festival. Its plain is one of the most densely populated regions on Earth. Pollution is a serious problem, and clean-up programmes are under way. Schematic.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#fef3c7\"/><path d=\"M30,40Q160,70 260,100T590,160\" fill=\"none\" stroke=\"#0891b2\" stroke-width=\"12\"/><circle cx=\"30\" cy=\"40\" r=\"8\" fill=\"#ea580c\" stroke=\"#fff\" stroke-width=\"2\"/><text x=\"30\" y=\"26\" text-anchor=\"start\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Himalayan glacier</text><circle cx=\"300\" cy=\"108\" r=\"8\" fill=\"#ea580c\" stroke=\"#fff\" stroke-width=\"2\"/><text x=\"300\" y=\"94\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Varanasi</text><circle cx=\"590\" cy=\"160\" r=\"8\" fill=\"#ea580c\" stroke=\"#fff\" stroke-width=\"2\"/><text x=\"590\" y=\"146\" text-anchor=\"end\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Delta in Bangladesh</text><text x=\"310\" y=\"192\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sacred in Hinduism; supports about 400 million people</text></svg>","c":"The Ganges from the Himalayas to the delta (schematic)"}]},"danube":{"t":"The Danube through ten countries","c":"The Danube, Europe’s second-longest river after the Volga at about 2,850 kilometres, flows from Germany’s Black Forest to the Black Sea, passing through or along the borders of ten countries, more than any other river in the world. Four capital cities stand on its banks: Vienna, Bratislava, Budapest and Belgrade. For centuries it has been a vital trade route and, at times, a frontier, such as the northern border of the Roman Empire. Its delta in Romania and Ukraine is a haven for birds. Schematic.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 160\" width=\"620\" height=\"160\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"160\" rx=\"10\" fill=\"#f8fafc\"/><path d=\"M20,80Q150,50 300,90T600,70\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"10\"/><circle cx=\"40\" cy=\"80.0\" r=\"6\" fill=\"#f59e0b\"/><text x=\"40\" y=\"44\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Germany</text><circle cx=\"100\" cy=\"88.7\" r=\"6\" fill=\"#f59e0b\"/><text x=\"100\" y=\"130\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Austria</text><circle cx=\"160\" cy=\"93.6\" r=\"6\" fill=\"#f59e0b\"/><text x=\"160\" y=\"44\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Slovakia</text><circle cx=\"220\" cy=\"92.7\" r=\"6\" fill=\"#f59e0b\"/><text x=\"220\" y=\"130\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Hungary</text><circle cx=\"280\" cy=\"86.4\" r=\"6\" fill=\"#f59e0b\"/><text x=\"280\" y=\"44\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Croatia</text><circle cx=\"340\" cy=\"77.3\" r=\"6\" fill=\"#f59e0b\"/><text x=\"340\" y=\"130\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Serbia</text><circle cx=\"400\" cy=\"69.4\" r=\"6\" fill=\"#f59e0b\"/><text x=\"400\" y=\"44\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Romania</text><circle cx=\"460\" cy=\"66.0\" r=\"6\" fill=\"#f59e0b\"/><text x=\"460\" y=\"130\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Bulgaria</text><circle cx=\"520\" cy=\"68.6\" r=\"6\" fill=\"#f59e0b\"/><text x=\"520\" y=\"44\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Moldova</text><circle cx=\"580\" cy=\"76.1\" r=\"6\" fill=\"#f59e0b\"/><text x=\"580\" y=\"130\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Ukraine</text></svg>","c":"Countries along the Danube, west to east (schematic)"}]},"mississippi":{"t":"The Mississippi river system","c":"The Mississippi flows about 3,700 kilometres from Lake Itasca in Minnesota to the Gulf of Mexico. Together with its great tributary the Missouri, it forms one of the longest river systems in the world, draining all or part of 31 US states and two Canadian provinces, about 40 percent of the continental United States. It has long been a highway for trade, from Native American canoes to steamboats celebrated by Mark Twain to today’s barges, and its fertile floodplain grows huge harvests. Schematic, not a map.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#f8fafc\"/><path d=\"M300,10V190\" stroke=\"#2563eb\" stroke-width=\"12\"/><path d=\"M60,60Q180,70 300,90M560,40Q430,70 300,110\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"7\"/><text x=\"100\" y=\"50\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Missouri</text><text x=\"520\" y=\"34\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Ohio</text><text x=\"310\" y=\"184\" text-anchor=\"start\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Gulf of Mexico</text><text x=\"310\" y=\"30\" text-anchor=\"start\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mississippi</text></svg>","c":"The Mississippi and two major tributaries (schematic)"}]},"madag":{"t":"Found nowhere else","c":"Madagascar, the world’s fourth-largest island, split from Africa about 160 million years ago and from India around 88 million years ago. Its plants and animals evolved in isolation, so a remarkably high share are found nowhere else on Earth: all its lemurs, most of its reptiles and amphibians, and the large majority of its plant species, including six of the world’s eight baobab species. Much of its original forest has been lost, putting many unique species at risk. Percentages are commonly cited estimates of endemic species.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 224\" width=\"620\" height=\"224\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"120\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Lemurs</text><rect x=\"130\" y=\"12\" width=\"340.0\" height=\"28\" rx=\"5\" fill=\"#a16207\"/><text x=\"478\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">100%</text><text x=\"120\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Amphibians</text><rect x=\"130\" y=\"52\" width=\"336.6\" height=\"28\" rx=\"5\" fill=\"#16a34a\"/><text x=\"474.6\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 99%</text><text x=\"120\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Reptiles</text><rect x=\"130\" y=\"92\" width=\"306.0\" height=\"28\" rx=\"5\" fill=\"#65a30d\"/><text x=\"444\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 90%</text><text x=\"120\" y=\"151\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Plants</text><rect x=\"130\" y=\"132\" width=\"272.0\" height=\"28\" rx=\"5\" fill=\"#22c55e\"/><text x=\"410\" y=\"151\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 80%</text><text x=\"120\" y=\"191\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Birds</text><rect x=\"130\" y=\"172\" width=\"170.0\" height=\"28\" rx=\"5\" fill=\"#2563eb\"/><text x=\"308\" y=\"191\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 50%</text></svg>","c":"Share of species found only on Madagascar (approximate)"}]},"med":{"t":"A sea between three continents","c":"The Mediterranean, about 2.5 million square kilometres, lies almost enclosed between Europe, Africa and Asia, linked to the Atlantic only by the Strait of Gibraltar, just 14 kilometres wide at its narrowest. Its name means ‘middle of the land’. It was the crossroads of many ancient civilisations, from Egypt, Phoenicia, Greece and Rome to the Byzantines, Arabs and Ottomans. Today its coasts are home to over 20 countries. Because rivers and rain cannot replace what evaporates, it is saltier than the Atlantic. Schematic.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#fef3c7\"/><path d=\"M20,150Q160,140 300,150T600,140V200H20Z\" fill=\"#38bdf8\"/><path d=\"M20,150Q160,140 300,150T600,140\" fill=\"none\" stroke=\"#0284c7\" stroke-width=\"3\"/><text x=\"150\" y=\"60\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"900\" fill=\"#78350f\" font-family=\"system-ui,sans-serif\">Europe</text><text x=\"520\" y=\"60\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"900\" fill=\"#78350f\" font-family=\"system-ui,sans-serif\">Asia</text><text x=\"310\" y=\"194\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"900\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Africa (south shore)</text><text x=\"310\" y=\"172\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Mediterranean Sea</text><text x=\"40\" y=\"130\" text-anchor=\"start\" font-size=\"11\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Strait of Gibraltar: only 14 km wide</text></svg>","c":"The Mediterranean between three continents (schematic)"}]},"sea":{"t":"The countries of Southeast Asia","c":"Southeast Asia is made up of 11 countries between China, India and Australia: mainland nations along the Mekong and great island nations scattered across seas, including Indonesia, the largest archipelago in the world, and the Philippines. About 680 million people live there, speaking hundreds of languages and following Buddhism, Islam, Christianity, Hinduism and local beliefs. Ten are members of ASEAN, and Timor-Leste is joining. The region’s history was shaped by Indian and Chinese influence, trade, empires such as Srivijaya and the Khmer, and colonial rule.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 226\" width=\"610\" height=\"226\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Brunei</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"210\" y=\"10\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"224\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cambodia</text><text x=\"224\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"410\" y=\"10\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"424\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Indonesia</text><text x=\"424\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"10\" y=\"64\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"92\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Laos</text><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"210\" y=\"64\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"224\" y=\"92\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Malaysia</text><text x=\"224\" y=\"112\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"410\" y=\"64\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#0891b2\" fill-opacity=\".2\" stroke=\"#0891b2\"/><text x=\"424\" y=\"92\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Myanmar</text><text x=\"424\" y=\"112\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"10\" y=\"118\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"146\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Philippines</text><text x=\"24\" y=\"166\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"210\" y=\"118\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"224\" y=\"146\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Singapore</text><text x=\"224\" y=\"166\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"410\" y=\"118\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"424\" y=\"146\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Thailand</text><text x=\"424\" y=\"166\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"10\" y=\"172\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"200\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Timor-Leste</text><text x=\"24\" y=\"220\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"210\" y=\"172\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"224\" y=\"200\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Vietnam</text><text x=\"224\" y=\"220\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text></svg>","c":"The 11 countries of Southeast Asia"}]},"hawaii":{"t":"How a hot spot built Hawaii","c":"The Hawaiian Islands sit in the middle of the Pacific Plate, far from any plate boundary. Beneath them, a plume of hot rock rising from deep in the mantle, called a hot spot, melts through the crust and builds volcanoes. As the plate slowly drifts northwest, about 7 centimetres a year, each volcano is carried away from the hot spot and goes extinct, while a new one forms. That is why the islands get older to the northwest and why the Big Island, still over the hot spot, has active volcanoes such as Kīlauea. Simplified cross-section.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#bae6fd\"/><path d=\"M0,140H620V200H0Z\" fill=\"#0284c7\"/><path d=\"M440,140L500,100L560,140Z\" fill=\"#16a34a\"/><text x=\"500\" y=\"90\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Older, worn-down islands</text><path d=\"M340,140L400,80L460,140Z\" fill=\"#22c55e\"/><path d=\"M240,140L300,60L360,140Z\" fill=\"#65a30d\"/><path d=\"M90,140L150,40L210,140Z\" fill=\"#78716c\"/><text x=\"150\" y=\"30\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Youngest island over the hot spot</text><path d=\"M150,200V150\" stroke=\"#dc2626\" stroke-width=\"10\"/><ellipse cx=\"150\" cy=\"200\" rx=\"40\" ry=\"10\" fill=\"#dc2626\"/><text x=\"150\" y=\"190\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Hot spot</text><path d=\"M560,180H420\" stroke=\"#fff\" stroke-width=\"3\"/><path d=\"M410,180l12,-6v12z\" fill=\"#fff\"/><text x=\"490\" y=\"172\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Pacific Plate moves</text></svg>","c":"A chain of volcanoes over a hot spot"}]},"galapagos":{"t":"Wildlife of the Galápagos","c":"The Galápagos Islands, about 1,000 kilometres off the coast of Ecuador, are volcanic islands where many animals evolved in isolation. Giant tortoises differ in shell shape from island to island, marine iguanas dive to graze on seaweed, and the islands host the only penguins that live at the equator. Charles Darwin’s visit in 1835 helped inspire his theory of evolution by natural selection. The islands are a national park and UNESCO World Heritage Site, and visitor numbers are strictly controlled.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 170\" width=\"610\" height=\"170\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#57534e\" fill-opacity=\".2\" stroke=\"#57534e\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Giant tortoises</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Each island’s shell shape differs</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#475569\" fill-opacity=\".2\" stroke=\"#475569\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Marine iguanas</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The only lizards that feed in the sea</text><rect x=\"10\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"118\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Blue-footed boobies</text><text x=\"24\" y=\"138\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dance to show off their feet</text><rect x=\"310\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"324\" y=\"118\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Darwin’s finches</text><text x=\"324\" y=\"138\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Beaks suited to different foods</text></svg>","c":"Four famous Galápagos animals"}]},"greenland":{"t":"The world’s largest islands","c":"Greenland is the world’s largest island, about 2.2 million square kilometres, though around four-fifths of it lies under an ice sheet up to 3 kilometres thick. Only about 57,000 people live there, mostly Inuit, along the ice-free coasts. It is a self-governing territory within the Kingdom of Denmark. Australia is larger but is counted as a continent. If Greenland’s ice melted entirely, global sea levels would rise by about 7 metres. Areas are approximate.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 224\" width=\"620\" height=\"224\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"160\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Greenland</text><rect x=\"170\" y=\"12\" width=\"300.0\" height=\"28\" rx=\"5\" fill=\"#94a3b8\"/><text x=\"478\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2,166 thousand km²</text><text x=\"160\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">New Guinea</text><rect x=\"170\" y=\"52\" width=\"108.9\" height=\"28\" rx=\"5\" fill=\"#16a34a\"/><text x=\"286.86426592797784\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">786 thousand km²</text><text x=\"160\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Borneo</text><rect x=\"170\" y=\"92\" width=\"103.6\" height=\"28\" rx=\"5\" fill=\"#65a30d\"/><text x=\"281.60110803324096\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">748 thousand km²</text><text x=\"160\" y=\"151\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Madagascar</text><rect x=\"170\" y=\"132\" width=\"81.3\" height=\"28\" rx=\"5\" fill=\"#a16207\"/><text x=\"259.30193905817174\" y=\"151\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">587 thousand km²</text><text x=\"160\" y=\"191\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Baffin Island</text><rect x=\"170\" y=\"172\" width=\"70.2\" height=\"28\" rx=\"5\" fill=\"#64748b\"/><text x=\"248.22160664819944\" y=\"191\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">507 thousand km²</text></svg>","c":"Areas of the largest islands (excluding Australia)"}]},"borneo":{"t":"One island, three countries","c":"Borneo, the third-largest island in the world, is shared by three countries: Indonesia’s Kalimantan covers most of the south, Malaysia’s states of Sabah and Sarawak lie in the north, and the small sultanate of Brunei sits on the northern coast. Its ancient rainforests are among the most biodiverse on Earth, home to orangutans, pygmy elephants, proboscis monkeys and the giant Rafflesia flower, but large areas have been cleared for logging and palm oil plantations. Shares of land area are approximate.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 144\" width=\"620\" height=\"144\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"200\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Indonesia (Kalimantan)</text><rect x=\"210\" y=\"12\" width=\"260.0\" height=\"28\" rx=\"5\" fill=\"#dc2626\"/><text x=\"478\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 73%</text><text x=\"200\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Malaysia (Sabah, Sarawak)</text><rect x=\"210\" y=\"52\" width=\"92.6\" height=\"28\" rx=\"5\" fill=\"#2563eb\"/><text x=\"310.6027397260274\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 26%</text><text x=\"200\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Brunei</text><rect x=\"210\" y=\"92\" width=\"4.0\" height=\"28\" rx=\"5\" fill=\"#f59e0b\"/><text x=\"222\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 1%</text></svg>","c":"Share of Borneo’s land area by country"}]},"sahel":{"t":"The Sahel: a transition zone","c":"The Sahel is a belt of semi-arid land stretching about 5,000 kilometres across Africa, from Senegal on the Atlantic to Sudan and Eritrea on the Red Sea, between the Sahara Desert to the north and wetter savannas to the south. Its name comes from the Arabic for ‘shore’ or ‘edge’. Rain falls only in a short wet season, so droughts can be devastating, as in the famines of the 1970s and 1980s. The Great Green Wall initiative aims to restore degraded land across the region. Schematic.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 190\" width=\"620\" height=\"190\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#fef3c7\"/><rect x=\"0\" y=\"20\" width=\"620\" height=\"50\" fill=\"#fde68a\"/><rect x=\"0\" y=\"70\" width=\"620\" height=\"60\" fill=\"#d9f99d\"/><rect x=\"0\" y=\"130\" width=\"620\" height=\"50\" fill=\"#86efac\"/><text x=\"310\" y=\"50\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#78350f\" font-family=\"system-ui,sans-serif\">Sahara Desert (north)</text><text x=\"310\" y=\"104\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"900\" fill=\"#365314\" font-family=\"system-ui,sans-serif\">Sahel: semi-arid grassland</text><text x=\"310\" y=\"160\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#14532d\" font-family=\"system-ui,sans-serif\">Savanna (south)</text></svg>","c":"The Sahel between desert and savanna (schematic)"}]},"patagonia":{"t":"Patagonia’s two faces","c":"Patagonia is the vast region at the southern tip of South America, shared by Argentina and Chile. In the west, the Andes rise in jagged granite peaks such as Fitz Roy and the Torres del Paine, with huge ice fields and glaciers, fjords and rainforests. To the east, in the rain shadow of the mountains, stretch windswept dry steppes grazed by sheep and guanacos. It is one of the least densely populated places on Earth. The name may come from the Patagones, giants said by Magellan’s crew to live there. Schematic.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#e0f2fe\"/><path d=\"M0,200L120,60L180,120L260,30L340,140L620,150V200Z\" fill=\"#78716c\"/><path d=\"M240,58L260,30L280,58Z\" fill=\"#f8fafc\"/><path d=\"M340,140L620,150V200H340Z\" fill=\"#fde68a\"/><text x=\"180\" y=\"180\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Andes and glaciers (west)</text><text x=\"480\" y=\"180\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#78350f\" font-family=\"system-ui,sans-serif\">Dry steppe (east)</text><text x=\"260\" y=\"22\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Fitz Roy, Torres del Paine</text></svg>","c":"From the Andes in the west to the steppe in the east (schematic)"}]},"polynesia":{"t":"The Polynesian Triangle","c":"Polynesia covers a vast triangle of the Pacific Ocean with corners at Hawaii, New Zealand and Easter Island, an area bigger than all of Africa, mostly open water. Beginning over 3,000 years ago, Polynesian navigators settled almost every habitable island within it in double-hulled voyaging canoes, finding their way without instruments by reading stars, swells, winds, clouds and birds. It was one of the greatest feats of exploration in human history. Today Polynesian cultures share related languages, traditions and a strong connection to the sea. Schematic.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 280\" width=\"620\" height=\"280\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:560px;max-width:100%;height:auto\"><rect width=\"620\" height=\"280\" rx=\"10\" fill=\"#0284c7\"/><path d=\"M310,40L130,240L500,230Z\" fill=\"none\" stroke=\"#bae6fd\" stroke-width=\"3\" stroke-dasharray=\"7 5\"/><circle cx=\"310\" cy=\"40\" r=\"9\" fill=\"#facc15\"/><text x=\"310\" y=\"26\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Hawaiʻi</text><circle cx=\"130\" cy=\"240\" r=\"9\" fill=\"#facc15\"/><text x=\"130\" y=\"264\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Aotearoa (New Zealand)</text><circle cx=\"500\" cy=\"230\" r=\"9\" fill=\"#facc15\"/><text x=\"500\" y=\"254\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Rapa Nui (Easter Island)</text><text x=\"330\" y=\"170\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#e0f2fe\" font-family=\"system-ui,sans-serif\">Samoa, Tonga, Tahiti, Cook Islands and more lie inside</text></svg>","c":"The corners of the Polynesian Triangle (schematic)"}]},"lagos":{"t":"Africa’s largest cities","c":"Lagos, Nigeria’s commercial capital on the Atlantic coast, is one of the largest and fastest-growing cities in Africa, with an estimated 15 to 20 million or more people in its metropolitan area. It is the heart of Nigeria’s economy and of Nollywood, one of the world’s biggest film industries, and of Afrobeats music. Africa is the fastest-urbanising continent, and several of its cities are expected to be among the world’s largest by mid-century. City population estimates vary widely between sources; figures here are approximate.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 264\" width=\"620\" height=\"264\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"150\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cairo</text><rect x=\"160\" y=\"12\" width=\"310.0\" height=\"28\" rx=\"5\" fill=\"#a16207\"/><text x=\"478\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">22 million</text><text x=\"150\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Kinshasa</text><rect x=\"160\" y=\"52\" width=\"239.5\" height=\"28\" rx=\"5\" fill=\"#2563eb\"/><text x=\"407.5454545454545\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">17 million</text><text x=\"150\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Lagos</text><rect x=\"160\" y=\"92\" width=\"225.5\" height=\"28\" rx=\"5\" fill=\"#16a34a\"/><text x=\"393.4545454545455\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">16 million</text><text x=\"150\" y=\"151\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Luanda</text><rect x=\"160\" y=\"132\" width=\"126.8\" height=\"28\" rx=\"5\" fill=\"#dc2626\"/><text x=\"294.8181818181818\" y=\"151\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">9 million</text><text x=\"150\" y=\"191\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Johannesburg</text><rect x=\"160\" y=\"172\" width=\"90.2\" height=\"28\" rx=\"5\" fill=\"#f59e0b\"/><text x=\"258.1818181818182\" y=\"191\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">6.4 million</text><text x=\"150\" y=\"231\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Nairobi</text><rect x=\"160\" y=\"212\" width=\"74.7\" height=\"28\" rx=\"5\" fill=\"#7c3aed\"/><text x=\"242.6818181818182\" y=\"231\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">5.3 million</text></svg>","c":"Approximate metropolitan populations, early 2020s"}]}});
